const preparedImages=new Map();
function prepareImage(path){if(!preparedImages.has(path))preparedImages.set(path,fetch(path).then(r=>{if(!r.ok)throw Error('image unavailable');return r.blob();}).then(blob=>new File([blob],path.split('/').pop(),{type:blob.type||'image/jpeg'})));return preparedImages.get(path);}
function readyImageButtons(){document.querySelectorAll('[data-share-image]').forEach(button=>{button.disabled=true;prepareImage(button.dataset.shareImage).then(()=>{if(button.isConnected)button.disabled=false;}).catch(()=>{if(button.isConnected){button.disabled=false;button.textContent='Abrir imagen';}});});}
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const user=()=>db.users[db.current];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){try{localStorage.setItem(key,JSON.stringify(db));storageOk=true;}catch{storageOk=false;toast('No se pudo guardar. Conserva esta ventana abierta y copia tus notas importantes antes de recargar.');}}
function event(type,detail={}){db.events.push({id:uid(),at:new Date().toISOString(),user:db.current,type,...detail});save();}
const link=(route,text,cls='btn')=>`<a class="${cls}" href="#/${route}">${text}</a>`;
const heading=(eyebrow,title,desc='')=>`<div class="page-heading"><span class="eyebrow">${eyebrow}</span><h1 tabindex="-1">${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}</div>`;
function copyButton(text,type,id,label='Copiar respuesta'){const k=uid();copyTexts.set(k,{text,type,id});return `<span class="copy-actions"><button class="btn secondary" data-copy="${k}">▣ ${label}</button>${['content_copied','response_copied','closing_copied'].includes(type)?`<button class="btn ghost" data-native-copy="${k}">Compartir texto ↗</button>`:''}</span>`;}
const nav=[['inicio','⌂','Inicio'],['secuencia','✦','Comienza aquí'],['mas/todo','☰','Todo'],...toolGroups.map(([id,label,icon])=>['mas/'+id,icon,label])];
const mobileNav=[['inicio','⌂','Inicio'],['productos','▦','Productos'],['compartir','↗','Compartir'],['practicar','◉','Practicar'],['mas','☰','Todo']];
function shell(html,route){
  const group=location.hash.split('/')[2]||'todo';const navRoute=route==='inicio'?'inicio':route==='secuencia'?'secuencia':route==='bandeja-testimonios'?'mas/testimonios':route==='mas'?'mas/'+(toolGroups.some(g=>g[0]===group)?group:'todo'):'mas/'+(directoryTools.find(t=>t[0]===route)?.[4]||'todo');
  const active=route==='compartir'?'compartir':route==='productos'?'productos':mobileNav.some(([r])=>r===route)?route:'mas';
  const bottom=mobileNav.map(([r,i,t])=>`<a href="#/${r}" class="mobile-nav-link ${active===r?'active':''} ${r==='compartir'?'share-link':''}" ${active===r?'aria-current="page"':''}><span aria-hidden="true">${i}</span><span>${t}</span></a>`).join('');
  return `<div class="shell"><aside class="sidebar"><a class="brand" href="#/inicio" aria-label="Bio4 Socios Inicio">bio<b>4</b> socios<small>CRECEMOS CONTIGO</small></a><nav aria-label="Navegación principal">${nav.map(([r,i,t])=>`<a href="#/${r}" class="${navRoute===r?'active':''}" ${navRoute===r?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${i}</span>${t}</a>`).join('')}</nav><div class="side-foot">${link('admin','Administración local','btn ghost small')}<p class="smallprint">Bio4 Socios V1<br>Asistente de Ventas y Arranque</p></div></aside><main class="main"><header class="topbar"><span class="eyebrow">UN PASO A LA VEZ. A TU RITMO.</span><button class="user-button" data-action="change-user" title="Cambiar de socio"><span class="avatar">${esc(user().name.slice(0,1).toUpperCase())}</span>${esc(user().name)} <span aria-hidden="true">⌄</span></button></header>${!storageOk?'<p class="notice">El navegador no permite guardar tu progreso. Los cambios se conservarán solo mientras esta ventana esté abierta.</p>':''}${html}<p class="footer-note">Guardado en este navegador · ${link('admin','Ver administración local','')} · <button class="btn ghost small" data-action="change-user">Cambiar de socio</button></p></main><nav class="mobile-nav" aria-label="Navegación principal móvil">${bottom}</nav></div>`;
}
function login(){return `<div class="login-wrap"><section class="login-story"><a class="brand">bio<b>4</b> socios</a><h1>Tu siguiente conversación<br>empieza aquí.</h1><p>Aprende sobre tus productos. Practica con confianza.<br>Acompaña a cada persona, a su ritmo.</p></section><section class="login-form"><form id="login"><span class="eyebrow">ASISTENTE DE VENTAS Y ARRANQUE</span><h2>Bienvenido a Bio4 Socios</h2><p class="muted">Un espacio para aprender, practicar y compartir.</p><label for="name">¿Cómo te llamas?</label><div class="field"><input id="name" name="name" autocomplete="given-name" placeholder="Tu nombre" required maxlength="60" pattern=".*\\S.*"></div><button class="btn" type="submit">Entrar a mi espacio →</button><p class="smallprint">V1 local · Tu nombre identifica tu progreso en este navegador. Este acceso no es una cuenta privada. Usa un nombre distinto si compartes el dispositivo.</p></form></section></div>`;}
function progressPage(){
  const current=user();
  const learned=new Set((Array.isArray(current.lessons)?current.lessons:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<lessons.length));
  const reviewed=new Set((Array.isArray(current.teamSteps)?current.teamSteps:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<teamSteps.length));
  const practiced=new Set(db.events.filter(e=>e.user===db.current&&e.type==='practice_completed'&&scenarios.some(s=>s.id===e.scenario)).map(e=>e.scenario));
  const followups=Array.isArray(current.followups)?current.followups:[];
  const open=followups.filter(f=>!f.done).length,finished=followups.filter(f=>f.done&&!f.cancelled).length;
  const active=current.practice&&!current.practice.completed;
  const nextLesson=lessons.findIndex((_,i)=>!learned.has(i));
  const nextScenario=scenarios.find(s=>!practiced.has(s.id));
  const nextTeam=teamSteps.findIndex((_,i)=>!reviewed.has(i));
  const tracks=[['Secuencia Mágica',sequenceCompleted(current).size,sequenceSteps.length,'secuencia','Actividades que marcaste en tu sistema paso a paso.'],['Aprender',learned.size,lessons.length,'aprender','Pasos que marcaste como hechos.'],['Practicar',practiced.size,scenarios.length,'practicar','Situaciones distintas completadas.'],['Equipo',reviewed.size,teamSteps.length,'equipo','Pasos de formación revisados.']];
  const done=[];
  if(learned.size)done.push([`${learned.size} paso${learned.size===1?'':'s'} de arranque marcado${learned.size===1?'':'s'}`, 'aprender']);
  if(practiced.size)done.push([`${practiced.size} situación${practiced.size===1?'':'es'} distinta${practiced.size===1?'':'s'} practicada${practiced.size===1?'':'s'}`, 'practicar']);
  if(reviewed.size)done.push([`${reviewed.size} paso${reviewed.size===1?'':'s'} de equipo revisado${reviewed.size===1?'':'s'}`, 'equipo']);
  if(finished)done.push([`${finished} seguimiento${finished===1?'':'s'} marcado${finished===1?'':'s'} como hecho${finished===1?'':'s'}`, 'seguimientos']);
  const reviewing=[];
  if(active)reviewing.push(['Conversación de práctica en curso','sesion']);
  if(open)reviewing.push([`${open} seguimiento${open===1?'':'s'} pendiente${open===1?'':'s'} de revisar`,'seguimientos']);
  const next=[];
  next.push(['Continúa tu Secuencia Mágica','secuencia']);
  next.push(['Continúa tu plan de 7 pasos','plan']);
  if(nextLesson>=0)next.push([`Paso ${nextLesson+1}: ${lessons[nextLesson].title}`,'aprender']);
  if(nextScenario)next.push([`Practica: ${nextScenario.title}`,'practicar']);
  if(nextTeam>=0)next.push([`Equipo: ${teamSteps[nextTeam].title}`,'equipo']);
  next.push(['Prepara un mensaje para compartir','compartir']);
  const column=(title,items,empty,kind)=>`<section class="card progress-column ${kind}"><h2>${title}</h2>${items.length?`<ul>${items.map(([label,route])=>`<li>${link(route,esc(label)+' →','progress-link')}</li>`).join('')}</ul>`:`<p class="muted">${empty}</p>`}</section>`;
  return heading('TU RUTA EN BIO4','Mi avance','Mira lo que revisaste, lo que dejaste en curso y el siguiente paso que puedes tomar.')+
    `<div class="progress-tracks">${tracks.map(([title,count,total,route,desc])=>`<a class="card progress-track" href="#/${route}"><span class="eyebrow">${title}</span><strong>${count} / ${total}</strong><div class="progress" role="progressbar" aria-label="${title}" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${Math.min(100,count/total*100)}%"></span></div><small>${desc}</small></a>`).join('')}</div>`+
    `<div class="section-line"><h2>Tu ruta, paso a paso</h2></div><div class="progress-board">${column('✓ Hecho',done,'Todavía no hay pasos registrados.','done')}${column('◷ En revisión',reviewing,'No tienes prácticas ni seguimientos pendientes.','review')}${column('→ Siguiente',next,'Completaste todos los pasos disponibles.','next')}</div>`+
    `<p class="smallprint">Este avance se guarda solo en este navegador. Marcar o revisar un paso no confirma mensajes enviados, ventas ni resultados de otros socios. Copiar un texto tampoco equivale a una venta.</p>`;
}
function weekCompleted(track){
  const saved=user().weeklyPlan?.[track];
  return new Set((Array.isArray(saved)?saved:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<weeklyPlans[track].steps.length));
}
function weeklyPlanPage(){
  const track=weeklyPlans[user().weeklyTrack]?user().weeklyTrack:'inicio';
  const plan=weeklyPlans[track],done=weekCompleted(track),next=plan.steps.findIndex((_,i)=>!done.has(i));
  return `<div class="notice">Tu ruta completa está en ${link('secuencia','Mi Secuencia Mágica →','')}. Este plan te ayuda a organizar una semana de práctica.</div>`+heading('UNA ACCIÓN A LA VEZ','Tu plan de 7 pasos','Una guía flexible para comenzar o acompañar a tu equipo. Puedes hacerla en una semana o seguir a tu ritmo.')+
    `<div class="plan-switch" role="group" aria-label="Elegir ruta">${Object.entries(weeklyPlans).map(([id,value])=>`<button class="btn ${track===id?'':'secondary'}" data-week-track="${id}" aria-pressed="${track===id}">${esc(value.title)}</button>`).join('')}</div>`+
    `<section class="card plan-intro"><div class="flex"><div><span class="eyebrow">TU RUTA</span><h2>${esc(plan.title)}</h2><p>${esc(plan.intro)}</p></div><span class="spacer"></span><span class="tag">${done.size} de ${plan.steps.length} pasos practicados</span></div><div class="progress" role="progressbar" aria-label="Pasos practicados de ${esc(plan.title)}" aria-valuenow="${done.size}" aria-valuemin="0" aria-valuemax="${plan.steps.length}"><span style="width:${done.size/plan.steps.length*100}%"></span></div><div class="flex"><p class="smallprint">Marca un paso cuando lo hagas o lo practiques. Es un registro manual; no comprueba mensajes enviados, pedidos ni ventas.</p><span class="spacer"></span>${next>=0?`<button class="btn secondary small" data-plan-jump="${next}">Ir al paso ${next+1} ↓</button>`:'<span class="tag">Ruta practicada · puedes volver a cualquier paso</span>'}</div></section>`+
    `<div class="plan-list">${plan.steps.map((step,i)=>`<article class="card plan-step ${done.has(i)?'completed':''} ${i===next?'up-next':''}" id="plan-step-${i}"><div class="plan-head"><span class="plan-number">${done.has(i)?'✓':i+1}</span><div><span class="eyebrow">PASO ${i+1}${i===next?' · SIGUIENTE':''}</span><h2>${esc(step.title)}</h2></div></div><p>${esc(step.action)}</p><div class="plan-coaching"><p><strong>Una pregunta útil:</strong> ${esc(step.question)}</p><p><strong>Cuida esto:</strong> ${esc(step.avoid)}</p></div><div class="plan-actions">${link(step.route,esc(step.button)+' →','btn secondary')}<label><input class="check" type="checkbox" data-week-step="${i}" ${done.has(i)?'checked':''}> Ya hice o practiqué este paso</label></div></article>`).join('')}</div>`+
    `<div class="notice">Usa este plan para preparar conversaciones, no para enviar mensajes desde la app. Contacta a personas que aceptaron recibir información y respeta si no quieren continuar. Los datos de esta ruta permanecen en este navegador.</div>`;
}
