  return heading(sharing?'ELIGE UN PRODUCTO':'CONOCE · COMPARTE',sharing?'Compartir':'Productos',sharing?'Encuentra el producto y prepara un texto para Catálogo, Estado o Chat.':'Busca por nombre o explora una categoría.')+`<div class="toolbar"><div class="search"><label for="product-search">Buscar producto</label><input type="search" id="product-search" placeholder="Nombre o presentación…" value="${esc(filters.q)}"></div></div><div class="category-chips" role="group" aria-label="Categorías de productos">${categories.map(([value,label])=>`<button class="category-chip ${value===filters.category?'active':''}" data-category="${esc(value)}" aria-pressed="${value===filters.category}">${label}</button>`).join('')}</div><div id="product-results">${productGrid()}</div><p class="smallprint">Precios de la base Bio4 2026, revisión del 16 de septiembre. Confirma el total y las condiciones antes de acordar un pedido.</p>`;
