if(b.dataset.shareOutcome){const p=currentProduct();if(!p||!sharingEligibility(p).enabled)return;const labels={response:'respuesta recibida',inquiry:'consulta sobre el producto',order:'pedido confirmado'};const outcome=b.dataset.shareOutcome;if(!labels[outcome])return;modal(`<h2>Registrar ${labels[outcome]}</h2><p>Para ${esc(p.name)}, variante ${shareVariant}. Confirma que ocurrió realmente y no lo habías registrado.</p><button class="btn" data-confirm-outcome="${outcome}">Confirmar registro</button>`);return;}
if(b.dataset.confirmOutcome){const p=currentProduct();if(!p||!sharingEligibility(p).enabled||!['response','inquiry','order'].includes(b.dataset.confirmOutcome))return;event('share_outcome',{item:p.id,variant:shareVariant,stage:shareStage,outcome:b.dataset.confirmOutcome});document.querySelector('dialog')?.close();render();toast('Resultado registrado; no se envió ningún mensaje.');return;}
